48	export default async function JurnalPage({
49	  params,
50	  searchParams,
51	}: {
52	  params: Promise<{ businessId: string }>;
53	  searchParams: Promise<{ period?: string; from?: string; to?: string }>;
54	}) {
55	  const { businessId } = await params;
56	  const { period: periodParam, from, to } = await searchParams;
57	  const cookieStore = await cookies();
58	  const period = parsePeriod(periodParam ?? cookieStore.get(PERIOD_COOKIE_NAME)?.value);
