3	import { useActionState, useState } from "react";
4	import type { JournalState } from "./actions";
5	
6	const initialState: JournalState = { error: null, resetToken: 0 };
7	
8	type Account = { code: string; name: string };
9	type Line = { accountCode: string; debit: string; credit: string };
10	
11	function emptyLine(defaultCode: string): Line {
12	  return { accountCode: defaultCode, debit: "", credit: "" };
13	}
14	
15	export default function AddJournalForm({
16	  action,
17	  today,
18	  accounts,
19	}: {
20	  action: (state: JournalState, formData: FormData) => Promise<JournalState>;
21	  today: string;
22	  accounts: Account[];
23	}) {
24	  const [state, formAction, pending] = useActionState(action, initialState);
25	
26	  return (
27	    <JournalFormFields
28	      key={state.resetToken}
29	      formAction={formAction}
30	      pending={pending}
31	      error={state.error}
32	      today={today}
33	      accounts={accounts}
34	    />
35	  );
36	}
