38	function JournalFormFields({
39	  formAction,
40	  pending,
41	  error,
42	  today,
43	  accounts,
44	}: {
45	  formAction: (formData: FormData) => void;
46	  pending: boolean;
47	  error: string | null;
48	  today: string;
49	  accounts: Account[];
50	}) {
51	  const defaultCode = accounts[0]?.code ?? "";
52	  const [lines, setLines] = useState<Line[]>([emptyLine(defaultCode), emptyLine(defaultCode)]);
53	
54	  function updateLine(i: number, patch: Partial<Line>) {
55	    setLines((prev) => prev.map((l, idx) => (idx === i ? { ...l, ...patch } : l)));
56	  }
57	
58	  function addLine() {
59	    setLines((prev) => [...prev, emptyLine(defaultCode)]);
60	  }
61	
62	  function removeLine(i: number) {
63	    setLines((prev) => (prev.length > 2 ? prev.filter((_, idx) => idx !== i) : prev));
64	  }
65	
66	  const totalDebit = lines.reduce((s, l) => s + (Number(l.debit) || 0), 0);
67	  const totalCredit = lines.reduce((s, l) => s + (Number(l.credit) || 0), 0);
68	  const balanced = Math.round(totalDebit * 100) === Math.round(totalCredit * 100);
69	
70	  const linesPayload = JSON.stringify(
71	    lines.map((l) => ({
72	      account_code: l.accountCode,
73	      debit: Number(l.debit) || 0,
74	      credit: Number(l.credit) || 0,
75	    })),
76	  );
77	
78	  return (
79	    <form action={formAction} className="space-y-3">
80	      <input type="hidden" name="lines" value={linesPayload} readOnly />
81	
82	      <div className="grid grid-cols-2 gap-2.5">
83	        <input
84	          name="date"
85	          type="date"
86	          defaultValue={today}
87	          required
88	          className="w-full rounded-xl border border-zinc-200 px-3 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
89	        />
90	        <input
91	          name="description"
92	          type="text"
93	          placeholder="Keterangan"
94	          required
95	          className="w-full rounded-xl border border-zinc-200 px-3 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
96	        />
97	      </div>
98	
99	      <div className="space-y-2">
100	        {lines.map((line, i) => (
101	          <div key={i} className="flex items-center gap-2">
102	            <select
103	              value={line.accountCode}
104	              onChange={(e) => updateLine(i, { accountCode: e.target.value })}
105	              className="min-w-0 flex-1 rounded-lg border border-zinc-200 px-2.5 py-2 text-xs focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
106	            >
107	              {accounts.map((a) => (
108	                <option key={a.code} value={a.code}>
109	                  {a.code} — {a.name}
110	                </option>
111	              ))}
112	            </select>
113	            <input
114	              type="number"
115	              min="0"
116	              placeholder="Debit"
117	              value={line.debit}
118	              onChange={(e) => updateLine(i, { debit: e.target.value, credit: "" })}
119	              className="w-24 shrink-0 rounded-lg border border-zinc-200 px-2.5 py-2 text-xs focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
120	            />
121	            <input
122	              type="number"
123	              min="0"
124	              placeholder="Kredit"
125	              value={line.credit}
126	              onChange={(e) => updateLine(i, { credit: e.target.value, debit: "" })}
127	              className="w-24 shrink-0 rounded-lg border border-zinc-200 px-2.5 py-2 text-xs focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
128	            />
129	            <button
130	              type="button"
131	              onClick={() => removeLine(i)}
132	              disabled={lines.length <= 2}
133	              className="shrink-0 text-xs text-zinc-400 hover:text-red-500 disabled:opacity-30"
134	              title="Hapus baris"
135	            >
136	              ✕
137	            </button>
138	          </div>
139	        ))}
140	      </div>
141	
142	      <button
143	        type="button"
144	        onClick={addLine}
145	        className="text-xs font-medium text-brand-600 hover:underline"
146	      >
147	        + Tambah baris
148	      </button>
149	
150	      <div
151	        className={`flex items-center justify-between rounded-lg px-3 py-2 text-xs font-semibold ${
152	          balanced ? "bg-brand-50 text-brand-700" : "bg-amber-50 text-amber-700"
153	        }`}
154	      >
155	        <span>Debit: {totalDebit.toLocaleString("id-ID")}</span>
156	        <span>Kredit: {totalCredit.toLocaleString("id-ID")}</span>
157	        <span>{balanced ? "✓ Seimbang" : "Belum seimbang"}</span>
158	      </div>
159	
160	      {error && (
161	        <p className="rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">{error}</p>
162	      )}
163	
164	      <button
165	        type="submit"
166	        disabled={pending || !balanced}
167	        className="rounded-lg bg-brand-600 px-4 py-2 text-xs font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
168	      >
169	        {pending ? "Menyimpan…" : "+ Posting Jurnal"}
170	      </button>
171	    </form>
172	  );
173	}
