3	import { revalidatePath } from "next/cache";
4	import { createClient } from "@/lib/supabase/server";
5	
6	export type JournalState = { error: string | null; resetToken: number };
7	
8	type LineInput = { account_code: string; debit: number; credit: number };
9	
10	export async function addJournalEntry(
11	  businessId: string,
12	  prevState: JournalState,
13	  formData: FormData,
14	): Promise<JournalState> {
15	  const fail = (msg: string): JournalState => ({ error: msg, resetToken: prevState.resetToken });
16	
17	  const date = formData.get("date") as string;
18	  const description = (formData.get("description") as string)?.trim();
19	  const linesRaw = formData.get("lines") as string;
20	
21	  if (!date) {
22	    return fail("Tanggal wajib diisi.");
23	  }
24	  if (!description) {
25	    return fail("Keterangan wajib diisi.");
26	  }
27	
28	  let lines: LineInput[];
29	  try {
30	    lines = JSON.parse(linesRaw);
31	  } catch {
32	    return fail("Baris jurnal tidak valid.");
33	  }
34	
35	  const validLines = lines.filter(
36	    (l) => l.account_code && (Number(l.debit) > 0 || Number(l.credit) > 0),
37	  );
38	
39	  if (validLines.length < 2) {
40	    return fail("Minimal 2 baris (debit dan kredit) harus diisi.");
41	  }
42	
43	  const totalDebit = validLines.reduce((s, l) => s + Number(l.debit), 0);
44	  const totalCredit = validLines.reduce((s, l) => s + Number(l.credit), 0);
45	
46	  if (Math.round(totalDebit * 100) !== Math.round(totalCredit * 100)) {
47	    return fail(
48	      `Jurnal belum seimbang: debit ${totalDebit.toLocaleString("id-ID")} ≠ kredit ${totalCredit.toLocaleString("id-ID")}.`,
49	    );
50	  }
51	
52	  const supabase = await createClient();
53	  const { error } = await supabase.rpc("post_journal_entry", {
54	    p_business_id: businessId,
55	    p_date: date,
56	    p_description: description,
57	    p_lines: validLines,
58	  });
59	
60	  if (error) {
61	    return fail(error.message);
62	  }
63	
64	  revalidatePath(`/business/${businessId}/accounting/jurnal`);
65	  return { error: null, resetToken: prevState.resetToken + 1 };
66	}
