1	-- Formal tutup buku (period closing). Before this, Neraca's "Laba Berjalan"
2	-- was always recomputed from every pendapatan/beban journal line since the
3	-- business's inception — there was no way to lock in a period's profit.
4	-- close_accounting_period() posts a closing entry that zeroes every
5	-- pendapatan/beban account's balance as of the chosen date and rolls the net
6	-- difference into 3-100 Laba Ditahan (retained earnings), which already
7	-- existed in the COA but nothing ever posted to it. Because the zeroing is
8	-- against each account's all-time cumulative balance (not a separate
9	-- "since last close" window), running the same balance query again after a
10	-- closing naturally reflects only activity since that closing — no other
11	-- report needs to change.
12	alter table public.journal_entries drop constraint if exists journal_entries_source_check;
13	alter table public.journal_entries add constraint journal_entries_source_check
14	  check (source in ('manual', 'penjualan', 'void', 'pembelian', 'beban', 'payroll', 'tutup_buku'));
15	
16	create table public.period_closings (
17	  id uuid primary key default gen_random_uuid(),
18	  business_id uuid not null references public.businesses (id) on delete cascade,
19	  period_end date not null,
20	  net_income numeric(14, 2) not null,
21	  journal_entry_id uuid references public.journal_entries (id) on delete set null,
22	  closed_at timestamptz not null default now(),
23	  unique (business_id, period_end)
24	);
25	
26	create index period_closings_business_id_idx on public.period_closings (business_id, period_end desc);
27	
28	alter table public.period_closings enable row level security;
29	
30	-- Read-only from the client — writes only happen through
31	-- close_accounting_period(), which validates ownership itself.
32	create policy "Owner views period closings of own businesses"
33	on public.period_closings for select
34	using (private.owns_business(business_id));
35	
36	create or replace function public.close_accounting_period(
37	  p_business_id uuid,
38	  p_period_end date
39	)
40	returns uuid
41	language plpgsql
42	security definer
43	set search_path = ''
44	as $$
45	declare
46	  v_as_of timestamptz;
47	  v_last_closed date;
48	  v_account record;
49	  v_lines jsonb := '[]'::jsonb;
50	  v_total_pendapatan numeric(14, 2) := 0;
51	  v_total_beban numeric(14, 2) := 0;
52	  v_net_income numeric(14, 2);
53	  v_entry_id uuid;
54	  v_closing_id uuid;
55	begin
56	  if not private.owns_business(p_business_id) then
57	    raise exception 'not authorized';
58	  end if;
59	
60	  if p_period_end > current_date then
61	    raise exception 'tanggal tutup buku tidak boleh di masa depan';
62	  end if;
63	
64	  select max(period_end) into v_last_closed
65	  from public.period_closings
66	  where business_id = p_business_id;
67	
68	  if v_last_closed is not null and p_period_end <= v_last_closed then
69	    raise exception 'tanggal harus setelah tutup buku terakhir (%)', v_last_closed;
70	  end if;
71	
72	  v_as_of := (p_period_end::text || 'T23:59:59+07:00')::timestamptz;
73	
74	  for v_account in
75	    select a.id, a.code, a.type,
76	      coalesce(sum(jl.debit) - sum(jl.credit), 0) as raw_balance
77	    from public.accounts a
78	    left join public.journal_lines jl on jl.account_id = a.id
79	    left join public.journal_entries je on je.id = jl.entry_id and je.date <= v_as_of
80	    where a.business_id = p_business_id and a.type in ('pendapatan', 'beban')
81	    group by a.id, a.code, a.type
82	    having coalesce(sum(jl.debit) - sum(jl.credit), 0) <> 0
83	  loop
84	    if v_account.type = 'pendapatan' then
85	      -- Credit-normal: raw_balance is negative when there's revenue booked.
86	      -- Debit it by the same magnitude to bring the cumulative balance to 0.
87	      v_lines := v_lines || jsonb_build_object(
88	        'account_code', v_account.code, 'debit', -v_account.raw_balance, 'credit', 0
89	      );
90	      v_total_pendapatan := v_total_pendapatan + (-v_account.raw_balance);
91	    else
92	      -- beban is debit-normal: raw_balance is positive when there's expense.
93	      -- Credit it by the same magnitude to zero it out.
94	      v_lines := v_lines || jsonb_build_object(
95	        'account_code', v_account.code, 'debit', 0, 'credit', v_account.raw_balance
96	      );
97	      v_total_beban := v_total_beban + v_account.raw_balance;
98	    end if;
99	  end loop;
100	
101	  if jsonb_array_length(v_lines) = 0 then
102	    raise exception 'tidak ada transaksi pendapatan/beban untuk ditutup pada periode ini';
103	  end if;
104	
105	  v_net_income := v_total_pendapatan - v_total_beban;
106	
107	  if v_net_income >= 0 then
108	    v_lines := v_lines || jsonb_build_object('account_code', '3-100', 'debit', 0, 'credit', v_net_income);
109	  else
110	    v_lines := v_lines || jsonb_build_object('account_code', '3-100', 'debit', -v_net_income, 'credit', 0);
111	  end if;
112	
113	  v_entry_id := private.post_journal(
114	    p_business_id, v_as_of, 'Tutup Buku periode s/d ' || p_period_end::text, 'tutup_buku', null, v_lines
115	  );
116	
117	  insert into public.period_closings (business_id, period_end, net_income, journal_entry_id)
118	  values (p_business_id, p_period_end, v_net_income, v_entry_id)
119	  returning id into v_closing_id;
120	
121	  return v_closing_id;
122	end;
123	$$;
124	
125	grant execute on function public.close_accounting_period(uuid, date) to authenticated;
